using AeroScience.Shared;

namespace AeroScience.Missions;

public static class SubmissionSupportingProducts
{
    public const int Version=1,DocumentVersion=2,MaximumProducts=3,MaximumTiles=256,MaximumSourceFiles=64,MaximumReferenceBytes=262144;
    public const string Disclosure="Reference-only supporting evidence for the completed flight. Includes selected source names/projects, historical dates or unknowns, CRS/height-reference declarations, original-file and derived-product hashes, processing method and modeled-corridor linkage. Source identities may disclose the research region. No original source files, terrain cells, point coordinates, viewer cache or profile values are attached. The receiver verifies received-byte/reference integrity, not the unshared original source. These references cannot satisfy original measurement requirements, increase observations/grades or approve campaign progress.";
    public static bool Eligible(PersonalResearchCard card)=>card.Survey is not null
        ||card.ObservationFlight?.SelectedInstruments.Contains("terrain-scanner")==true;
    static bool Digest(string? value)=>value is {Length:64}&&value.All(char.IsAsciiHexDigit);
    static bool Text(string? value,int maximum=4000)=>value is not null&&value.Length<=maximum;
    public static string EvidenceClass(string kind)=>kind switch{
        ContinuousTerrainSurveys.ArtifactKind=>"Modeled scanner support, not measured elevation or laser coverage",
        TerrainElevations.IndexKind=>"Historical source-backed native elevation cells; not new flight observations",
        LidarProcessing.IndexKind=>"Original historical delivered LiDAR returns; not generated by the simulator",
        _=>throw new ArgumentException("This artifact kind is not eligible supporting evidence.")};
    static string Algorithm(string kind)=>kind switch{
        ContinuousTerrainSurveys.ArtifactKind=>ContinuousTerrainSurveys.Algorithm,
        TerrainElevations.IndexKind=>TerrainElevations.Algorithm,
        LidarProcessing.IndexKind=>LidarProcessing.Algorithm,
        _=>"unsupported"};
    public static SubmissionSupportingProduct Read(ScienceStore science,MissionStore missions,Guid flight,Guid id,CancellationToken ct=default)
    {
        using var lease=science.BeginAnalysis();
        var artifact=science.Artifact(id);if(artifact.MissionId!=flight)throw new ArgumentException("Choose a supporting product from this exact completed flight.");
        var manifest=SurveyResults.Manifest(science,missions,id,missions.SupportingProductPreferences?.Invoke(),ct);
        if(manifest.Tiles.Length>MaximumTiles)throw new NotSupportedException("This supporting reference exceeds 256 tile identities. Select a smaller regional product; no references were truncated.");
        var sources=manifest.Sources.Select(s=>{
            ct.ThrowIfCancellationRequested();var original=science.Source(s.Id)??throw new IOException("A selected supporting source was deleted.");
            if(original.Files.Length>MaximumSourceFiles)throw new NotSupportedException("This reference exceeds 64 original file identities per source. No files were silently omitted.");
            return new SubmissionSupportingSource(s.Id,s.Name,s.Project,s.Surface,s.Unit,s.HorizontalCrs,s.VerticalReference,s.ReferenceVerified,s.ObservationUtc,
                s.ManifestSha256,original.Files.Select((f,n)=>new SubmissionOriginalFileReference(n,f.Bytes,f.Sha256)).ToArray(),s.Dimensions,s.License,s.Citation);
        }).ToArray();
        var product=new SubmissionSupportingProduct(Version,id,flight,manifest.Kind,artifact.Sha256,artifact.Bytes,artifact.CreatedUtc,
            manifest.GeometryId,manifest.GeometrySha256,manifest.InputFingerprint,manifest.Algorithm,manifest.EvidenceClass,sources,
            manifest.Tiles.Select(t=>new SubmissionSupportingTile(t.Id,t.Sha256,t.Bytes,t.SourceId,t.Records,t.Missing)).ToArray(),manifest.Values,manifest.Missing,
            manifest.Limitations,Disclosure,true,false);
        Validate(product,flight);return product;
    }
    public static void Validate(SubmissionSupportingProduct p,Guid flight)
    {
        if(p is null||p.Version!=Version||p.Id==Guid.Empty||p.FlightId!=flight||!p.ReferenceOnly||p.GrantsOriginalScienceCredit||p.Disclosure!=Disclosure
            ||!Digest(p.Sha256)||p.Bytes is <1 or >SurveyResults.MaximumProductBytes||p.ProcessedUtc==default||p.ProcessedUtc.Offset!=TimeSpan.Zero
            ||p.GeometryId==Guid.Empty||!Digest(p.GeometrySha256)||!Digest(p.InputFingerprint)||p.Algorithm!=Algorithm(p.Kind)||p.EvidenceClass!=EvidenceClass(p.Kind)
            ||p.ReferencedValues is <0 or >1000000000||p.ReferencedMissing is <0 or >1000000000||p.Sources is not {Length:<=16}||p.Sources.Any(s=>s is null)||p.Sources.Select(s=>s.Id).Distinct().Count()!=p.Sources.Length
            ||p.Tiles is not {Length:<=MaximumTiles}||p.Tiles.Any(t=>t is null)||p.Tiles.Select(t=>t.Id).Distinct().Count()!=p.Tiles.Length
            ||p.Limitations is not {Length:>=1 and <=64}||p.Limitations.Any(s=>!Text(s)))throw new ArgumentException("Unsupported supporting-product identity, bounds or scientific disclosure.");
        foreach(var s in p.Sources){
            if(s.Id==Guid.Empty||!Text(s.Name,500)||!Text(s.Project,500)||!Text(s.Surface,100)||!Text(s.Unit,100)||!Text(s.HorizontalCrs)||!Text(s.VerticalReference)
                ||!Text(s.License)||!Text(s.Citation)||!Digest(s.ManifestSha256)||s.Originals is not {Length:>=1 and <=MaximumSourceFiles}
                ||s.Originals.Where((f,n)=>f is null||f.Ordinal!=n||f.Bytes<0||!Digest(f.Sha256)).Any()
                ||s.Dimensions is not {Length:>=1 and <=128}||s.Dimensions.Any(d=>!Text(d,200)))throw new ArgumentException("Invalid original-source reference. Missing metadata cannot be reconstructed.");
            if(s.ReferenceVerified&&(SurveyResults.Unverified(s.VerticalReference)||s.Unit is not("m" or "ft")))throw new ArgumentException("Unknown vertical metadata cannot be promoted to verified height.");
            if(p.Kind==LidarProcessing.IndexKind&&s.Surface!="historical-lidar"||p.Kind==TerrainElevations.IndexKind&&s.Surface is not("dem" or "dsm" or "composite-dem" or "unknown"))throw new ArgumentException("Historical point and DEM/DSM source classes cannot be substituted.");
        }
        foreach(var t in p.Tiles)if(t.Id==Guid.Empty||!Digest(t.Sha256)||t.Bytes<1||t.Values is <0 or >1000000000||t.Missing is <0 or >1000000000||!p.Sources.Any(s=>s.Id==t.SourceId))throw new ArgumentException("A supporting tile refers to another source or invalid data identity.");
        if(p.Kind==ContinuousTerrainSurveys.ArtifactKind){if(p.Sources.Length!=0||p.Tiles.Length!=0||p.ReferencedValues!=0||p.ReferencedMissing!=0||p.Id!=p.GeometryId||p.Sha256!=p.GeometrySha256)throw new ArgumentException("Modeled support is not historical measurement evidence.");}
        else if(p.Sources.Length==0||p.Tiles.Sum(t=>t.Values)!=p.ReferencedValues||p.Tiles.Sum(t=>t.Missing)!=p.ReferencedMissing)throw new ArgumentException("Supporting source/tile counts differ from the referenced product.");
        if(SubmissionEvidenceProtocol.Bytes(p)>MaximumReferenceBytes)throw new NotSupportedException("A supporting reference exceeds the 256 KiB bound. Select a smaller product.");
    }
}

public sealed partial class MissionStore
{
    // Engine supplies the existing host settings getter; no separate source policy.
    public Func<ScientificAccessPreferences>? SupportingProductPreferences {get;set;}
    public SubmissionSupportingChoices SupportingSubmissionChoices(ScienceStore science,SubmissionSupportingRequest request,CancellationToken ct=default)
    {
        if(request.ResultIds is not {Length:>=1 and <=16}||request.ResultIds.Any(id=>id==Guid.Empty)||request.ResultIds.Distinct().Count()!=request.ResultIds.Length)throw new ArgumentException("Choose 1–16 exact saved research results.");
        var mission=Detail(request.FlightId)?.Mission??throw new ArgumentException("Choose a retained completed flight.");
        if(mission.Status==MissionStatus.Recording||mission.EndedUtc is null)throw new ArgumentException("Complete the flight before selecting supporting references.");
        var results=request.ResultIds.Select(ResearchAttempt).ToArray();
        if(results.Any(r=>r.FlightId!=request.FlightId||r.Card.OrganizationAssignment is null))throw new ArgumentException("Only the original organizational results from this flight can select supporting evidence.");
        var eligible=results.Any(r=>SubmissionSupportingProducts.Eligible(r.Card));
        return new(eligible,eligible?SurveyResults.Catalog(science,this,request.FlightId,ct).Select(p=>new SubmissionSupportingChoice(p.Id,p.Kind,p.Sha256,p.Bytes,p.State,p.Reason)).ToArray():[],SubmissionSupportingProducts.Disclosure);
    }
}
